    void refreshList(){Library.Asset old=selected;syncing=true;model.clear();String q=search.getText().strip().toLowerCase(Locale.ROOT);for(Library.Asset a:library.assets)if((!favoritesOnly.isSelected()||a.favorite)&&a.name.toLowerCase(Locale.ROOT).contains(q))model.addElement(a);if(old!=null&&model.contains(old))list.setSelectedValue(old,true);syncing=false;}
    void select(Library.Asset a){
        if(a==null){
            selected=null;previewClip=null;previewTime=0;
            selectedName.setText("Your library is empty");
            meta.setText("Import a GIF, APNG or image to begin");
            syncing=true;list.clearSelection();favorite.setSelected(false);syncing=false;
            favorite.setEnabled(false);flip.setEnabled(false);size.setEnabled(false);speed.setEnabled(false);opacity.setEnabled(false);
            preview.repaint();return;
        }
        favorite.setEnabled(true);flip.setEnabled(true);size.setEnabled(true);speed.setEnabled(true);opacity.setEnabled(true);
        selected=a;previewClip=null;previewTime=0;selectedName.setText(a.name);meta.setText("Loading preview…");syncControls();syncing=true;list.setSelectedValue(a,true);syncing=false;
        if(a.clip!=null){previewClip=a.clip;showMeta(a);return;}
        new SwingWorker<Media.Clip,Void>(){protected Media.Clip doInBackground()throws Exception{return a.load(library.data);}protected void done(){try{Media.Clip c=get();if(selected==a){previewClip=c;showMeta(a);}}catch(Exception ex){if(selected==a){meta.setText("File unavailable — import it again");status("Could not load "+a.name+": "+message(ex));}}}}.execute();
    }
    void showMeta(Library.Asset a){meta.setText(a.type()+"  ·  "+a.clip.width()+" × "+a.clip.height()+"  ·  "+a.clip.frames().size()+" frames");}
    void syncControls(){if(selected==null)return;syncing=true;size.setValue(Math.min(600,selected.size));speed.setValue((int)(selected.speed*100));opacity.setValue((int)(selected.opacity*100));sizeValue.setText(selected.size+" px");speedValue.setText(String.format(Locale.ROOT,"%.2f×",selected.speed));opacityValue.setText(Math.round(selected.opacity*100)+"%");flip.setSelected(selected.flip);favorite.setSelected(selected.favorite);syncing=false;}
    void applySettings(){for(DesktopSprite s:sprites)s.resizeSprite();syncControls();preview.repaint();if(!size.getValueIsAdjusting()&&!speed.getValueIsAdjusting()&&!opacity.getValueIsAdjusting())persist();}
    void spawn(Library.Asset a){if(sprites.size()>=24){status("The desktop can hold up to 24 characters.");return;}if(a.clip==null){status("Wait for this animation to finish loading.");return;}try{DesktopSprite s=new DesktopSprite(this,a,a.clip);Rectangle r=frame.getGraphicsConfiguration().getBounds();Insets in=Toolkit.getDefaultToolkit().getScreenInsets(frame.getGraphicsConfiguration());s.setLocation(r.x+r.width-s.getWidth()-70-(sprites.size()%5)*55,r.y+r.height-in.bottom-s.getHeight()-24);sprites.add(s);s.setVisible(!hidden);updateCount();playSound(a);status(a.name+" is on your desktop.");}catch(Exception ex){error(ex);}}
    void removeSprite(DesktopSprite s){sprites.remove(s);s.dispose();updateCount();}
    void removeSelected(){if(selected!=null)for(DesktopSprite s:List.copyOf(sprites))if(s.asset==selected)removeSprite(s);status("Selected character removed from desktop.");}
    void clearDesktop(){for(DesktopSprite s:List.copyOf(sprites))removeSprite(s);status("Desktop cleared.");}
    void togglePause(){paused=!paused;pauseButton.setText(paused?"Resume all":"Pause all");status(paused?"Animations paused.":"Animations playing.");}
    void toggleHidden(){hidden=!hidden;for(DesktopSprite s:sprites)s.setVisible(!hidden);hideButton.setText(hidden?"Show all":"Hide all");status(hidden?"Characters hidden. Use Show all or the tray menu to restore them.":"Characters visible.");}
    void updateCount(){count.setText(sprites.size()+" on desktop");}
    void importFiles(){JFileChooser fc=chooser("Images and animations","png","apng","gif","jpg","jpeg","bmp");fc.setMultiSelectionEnabled(true);if(fc.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION)importPaths(Arrays.stream(fc.getSelectedFiles()).map(File::toPath).toList());}
    void importPaths(List<Path> paths){if(busy){status("Please wait for the current import to finish.");return;}busy=true;status("Importing animations…");new SwingWorker<List<Library.Asset>,Void>(){final List<String> errors=new ArrayList<>();protected List<Library.Asset> doInBackground(){List<Library.Asset> result=new ArrayList<>();for(Path p:paths)try{Media.Clip c=Media.load(p);synchronized(library){result.add(library.add(p,c));}}catch(Exception ex){errors.add(p.getFileName()+": "+message(ex));}return result;}protected void done(){busy=false;try{List<Library.Asset> result=get();refreshList();if(!result.isEmpty()){favoritesOnly.setSelected(false);search.setText("");refreshList();select(result.get(result.size()-1));}status(result.size()+" animation(s) imported.");if(!errors.isEmpty())JOptionPane.showMessageDialog(frame,String.join("\n",errors),"Some files could not be imported",JOptionPane.WARNING_MESSAGE);}catch(Exception ex){error(ex);}}}.execute();}
    void rename(){if(selected==null)return;String name=JOptionPane.showInputDialog(frame,"Animation name",selected.name);if(name!=null&&!name.isBlank()){selected.name=name.strip().substring(0,Math.min(100,name.strip().length()));selectedName.setText(selected.name);persist();refreshList();}}
    void removeAsset() {
        if (selected == null) { status("Select an imported animation first."); return; }
        if (busy) { status("Wait for the current import or conversion to finish."); return; }
        String warning = "Delete “" + selected.name + "” from your library?\n"
            + "Its imported copy and assigned sound will be deleted. Your original files stay untouched.\n"
            + "Saved scenes using this animation will need updating.";
        if (JOptionPane.showConfirmDialog(frame, warning, "Delete animation",
                JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) != JOptionPane.OK_OPTION) return;
        try { deleteAsset(selected); status("Animation deleted from the library."); }
        catch (IOException ex) { refreshList(); select(model.isEmpty()?null:model.get(0)); error(ex); }
    }

    void deleteAsset(Library.Asset asset) throws IOException {
        if (soundClip != null) { soundClip.stop(); soundClip.close(); soundClip = null; }
        try { library.delete(asset); }
        finally {
            if (!library.assets.contains(asset)) {
                for (DesktopSprite sprite : List.copyOf(sprites)) if (sprite.asset == asset) removeSprite(sprite);
                refreshList();
                select(model.isEmpty()?null:model.get(0));
            }
        }
    }
    void assignSound(){if(selected==null)return;JFileChooser fc=chooser("Audio (WAV, AIFF, AU)","wav","aiff","aif","au");if(fc.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION)try{Path source=fc.getSelectedFile().toPath();if(Files.size(source)>20_000_000)throw new IOException("Choose an audio file smaller than 20 MB.");try(AudioInputStream audio=AudioSystem.getAudioInputStream(source.toFile())){if(audio.getFrameLength()<=0)throw new IOException("Audio file is empty.");}String dest="assets/"+UUID.randomUUID()+"-"+source.getFileName();Files.copy(source,library.data.resolve(dest));selected.sound=dest;persist();playSound(selected);status("Sound assigned; it plays when this character spawns.");}catch(Exception ex){error(ex);}}
    void playSound(Library.Asset a){if(a.sound.isEmpty())return;try{if(soundClip!=null)soundClip.close();try(AudioInputStream audio=AudioSystem.getAudioInputStream(library.data.resolve(a.sound).toFile())){soundClip=AudioSystem.getClip();soundClip.open(audio);soundClip.start();}}catch(Exception ex){status("Character loaded, but its sound could not play: "+message(ex));}}
    void importSheet(){JFileChooser fc=chooser("Sprite sheet PNG","png");if(fc.showOpenDialog(frame)!=JFileChooser.APPROVE_OPTION)return;JSpinner cols=new JSpinner(new SpinnerNumberModel(4,1,100,1)),rows=new JSpinner(new SpinnerNumberModel(4,1,100,1)),frames=new JSpinner(new SpinnerNumberModel(16,1,600,1)),fps=new JSpinner(new SpinnerNumberModel(12,1,60,1));JPanel fields=new JPanel(new GridLayout(4,2,12,10));fields.add(new JLabel("Columns"));fields.add(cols);fields.add(new JLabel("Rows"));fields.add(rows);fields.add(new JLabel("Frame count"));fields.add(frames);fields.add(new JLabel("Frames / second"));fields.add(fps);if(JOptionPane.showConfirmDialog(frame,fields,"Slice sprite sheet",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;Path source=fc.getSelectedFile().toPath();work("Building animation…",()->{Media.Clip still=Media.load(source);return Media.sheet(still.frames().get(0),(int)cols.getValue(),(int)rows.getValue(),(int)frames.getValue(),(int)fps.getValue());},c->addCreated(source.getFileName()+" · sprites",c));}
    void removeColor(){if(previewClip==null){status("Select a loaded animation in Animation Menu first.");return;}Color key=JColorChooser.showDialog(frame,"Background color to remove",Color.WHITE);if(key==null)return;JSlider tolerance=new JSlider(0,160,35);tolerance.setMajorTickSpacing(40);tolerance.setPaintTicks(true);tolerance.setPaintLabels(true);if(JOptionPane.showConfirmDialog(frame,tolerance,"Color tolerance (0 = exact match)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;Media.Clip src=previewClip;String name=selected.name;work("Removing background color…",()->Media.key(src,key,tolerance.getValue()),c->addCreated(name+" · cutout",c));}
    void addCreated(String name,Media.Clip clip){work("Saving animation…",()->{synchronized(library){return library.addClip(name,clip);}},a->{favoritesOnly.setSelected(false);search.setText("");refreshList();select(a);navigate("Animation Menu");status("Animation created and added to your library.");});}
    void exportMedia(){if(previewClip==null){status("Select a loaded animation first.");return;}Object format=JOptionPane.showInputDialog(frame,"Export format","Export animation",JOptionPane.PLAIN_MESSAGE,null,new String[]{"Animated GIF","Current frame PNG"},"Animated GIF");if(format==null)return;boolean gif=format.equals("Animated GIF");JFileChooser fc=chooser(gif?"GIF":"PNG",gif?"gif":"png");fc.setSelectedFile(new File("animation."+(gif?"gif":"png")));if(fc.showSaveDialog(frame)!=JFileChooser.APPROVE_OPTION)return;Path f=extension(fc.getSelectedFile().toPath(),gif?".gif":".png");if(!overwrite(f))return;Media.Clip c=previewClip;BufferedImage current=c.at(previewTime);work("Exporting…",()->{if(gif)Media.writeGif(c,f);else ImageIO.write(current,"png",f.toFile());return f;},x->status("Exported "+x.getFileName()));}
    void convertVideo(){JFileChooser fc=chooser("Video, animated WebP or APNG","mp4","webm","mov","mkv","webp","apng");if(fc.showOpenDialog(frame)!=JFileChooser.APPROVE_OPTION)return;Path source=fc.getSelectedFile().toPath();String ffmpeg=library.prefs.getProperty("ffmpeg","ffmpeg");work("Converting first 8 seconds with FFmpeg…",()->{
        Path out=Files.createTempFile(library.data,"conversion-",".gif"),log=Files.createTempFile(library.data,"converter-",".log");try{
            Process process;try{process=new ProcessBuilder(ffmpeg,"-nostdin","-y","-i",source.toAbsolutePath().toString(),"-t","8","-vf","fps=15,scale=320:-1:flags=lanczos","-loop","0",out.toString()).redirectErrorStream(true).redirectOutput(log.toFile()).start();}catch(IOException ex){throw new IOException("FFmpeg was not found. Set the path to your ffmpeg.exe in Configuration.");}
            if(!process.waitFor(90,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor();throw new IOException("Conversion timed out.");}if(process.exitValue()!=0)throw new IOException("FFmpeg could not decode this file. Check that it is valid and supported.");Media.Clip c=Media.load(out);synchronized(library){Library.Asset a=library.add(out,c);a.name=source.getFileName()+" · converted";library.save();return a;}
        }finally{Files.deleteIfExists(out);Files.deleteIfExists(log);}
    },a->{refreshList();select(a);navigate("Animation Menu");status("Converted media added to the library.");});}
    interface Task<T>{T run()throws Exception;}
    <T>void work(String text,Task<T> task,java.util.function.Consumer<T> success){if(busy){status("Please wait for the current operation to finish.");return;}busy=true;status(text);new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return task.run();}protected void done(){busy=false;try{success.accept(get());}catch(Exception ex){error(ex);}}}.execute();}
    void saveSceneDialog(){String name=JOptionPane.showInputDialog(frame,"Scene name","My desktop");if(name==null||name.isBlank())return;name=name.strip().replaceAll("[^\\p{L}\\p{N} ._-]","_");if(name.length()>80)name=name.substring(0,80);Path f=library.data.resolve("scenes").resolve(name+".scene");if(!overwrite(f))return;try{saveScene(f);refreshScenes();status("Scene saved: "+name);}catch(Exception ex){error(ex);}}
    void saveScene(Path path)throws IOException{Properties p=new Properties();p.setProperty("format","AnimeSpawner/1");p.setProperty("count",""+sprites.size());for(int i=0;i<sprites.size();i++){DesktopSprite s=sprites.get(i);String k="sprite."+i+".";p.setProperty(k+"asset",s.asset.id);p.setProperty(k+"x",""+s.getX());p.setProperty(k+"y",""+s.getY());p.setProperty(k+"size",""+s.asset.size);p.setProperty(k+"speed",""+s.asset.speed);p.setProperty(k+"opacity",""+s.asset.opacity);p.setProperty(k+"flip",""+s.asset.flip);p.setProperty(k+"paused",""+s.paused);p.setProperty(k+"locked",""+s.locked);}Library.write(p,path);}
    record SceneItem(Library.Asset asset,int x,int y,int size,double speed,double opacity,boolean flip,boolean paused,boolean locked){}
    List<SceneItem> readScene(Path path)throws IOException{if(Files.size(path)>1_000_000)throw new IOException("Scene file is too large.");Properties p=new Properties();try(InputStream in=Files.newInputStream(path)){p.load(in);}if(!"AnimeSpawner/1".equals(p.getProperty("format")))throw new IOException("Not an Anime Spawner scene.");int n=Library.integer(p,"count",0,0,24);List<SceneItem> result=new ArrayList<>();for(int i=0;i<n;i++){String k="sprite."+i+".";Library.Asset a=library.find(p.getProperty(k+"asset"));if(a==null)throw new IOException("This scene references an animation not in your library. Import its original library first.");a.load(library.data);result.add(new SceneItem(a,Library.integer(p,k+"x",50,-50000,50000),Library.integer(p,k+"y",50,-50000,50000),Library.integer(p,k+"size",260,64,1000),Library.decimal(p,k+"speed",1,.1,4),Library.decimal(p,k+"opacity",1,.1,1),Boolean.parseBoolean(p.getProperty(k+"flip")),Boolean.parseBoolean(p.getProperty(k+"paused")),Boolean.parseBoolean(p.getProperty(k+"locked"))));}return result;}
    void loadScene(Path path){work("Loading scene…",()->readScene(path),items->{clearDesktop();for(SceneItem item:items){Library.Asset a=item.asset();a.size=item.size();a.speed=item.speed();a.opacity=item.opacity();a.flip=item.flip();DesktopSprite s=new DesktopSprite(this,a,a.clip);s.setLocation(item.x(),item.y());s.paused=item.paused();s.locked=item.locked();s.keepOnScreen();sprites.add(s);s.setVisible(!hidden);}syncControls();updateCount();persist();status("Scene loaded: "+path.getFileName());});}
    void refreshScenes(){sceneModel.clear();try(var paths=Files.list(library.data.resolve("scenes"))){paths.filter(p->p.toString().endsWith(".scene")).sorted().forEach(p->{String n=p.getFileName().toString();sceneModel.addElement(n.substring(0,n.length()-6));});}catch(IOException ex){error(ex);}}
    void setupTray(){if(!SystemTray.isSupported())return;try{PopupMenu menu=new PopupMenu();trayItem(menu,"Open Anime Spawner",this::showManager);trayItem(menu,"Show / hide characters",this::toggleHidden);trayItem(menu,"Pause / resume",this::togglePause);trayItem(menu,"Center all characters",()->{for(DesktopSprite s:sprites)s.center();});menu.addSeparator();trayItem(menu,"Quit",this::quit);tray=new TrayIcon(Artwork.icon(),"Anime Spawner",menu);tray.setImageAutoSize(true);tray.addActionListener(e->showManager());SystemTray.getSystemTray().add(tray);}catch(Exception ex){tray=null;}}
    void trayItem(PopupMenu p,String name,Runnable task){MenuItem item=new MenuItem(name);item.addActionListener(e->SwingUtilities.invokeLater(task));p.add(item);}
    void setupShortcuts(){bind("control O","import",this::importFiles);bind("control S","save",this::saveSceneDialog);bind("control H","hide",this::toggleHidden);bind("control P","pause",this::togglePause);}
    void bind(String key,String name,Runnable task){frame.getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key),name);frame.getRootPane().getActionMap().put(name,new AbstractAction(){public void actionPerformed(ActionEvent e){task.run();}});}
    void setupDrop(){TransferHandler drop=new TransferHandler(){public boolean canImport(TransferSupport s){return s.isDataFlavorSupported(DataFlavor.javaFileListFlavor);}public boolean importData(TransferSupport s){if(!canImport(s))return false;try{@SuppressWarnings("unchecked")List<File> files=(List<File>)s.getTransferable().getTransferData(DataFlavor.javaFileListFlavor);importPaths(files.stream().map(File::toPath).toList());return true;}catch(Exception ex){error(ex);return false;}}};list.setTransferHandler(drop);preview.setTransferHandler(drop);frame.getRootPane().setTransferHandler(drop);}
    void showManager(){frame.setVisible(true);frame.setState(Frame.NORMAL);frame.toFront();}
    void quit(){if(busy){status("Wait for the current operation to finish before quitting.");showManager();return;}try{saveScene(library.data.resolve("last-session.scene"));library.save();}catch(IOException ex){error(ex);return;}timer.stop();for(DesktopSprite s:sprites)s.dispose();if(soundClip!=null)soundClip.close();if(tray!=null)SystemTray.getSystemTray().remove(tray);frame.dispose();System.exit(0);}
    void persist(){try{synchronized(library){library.save();}}catch(IOException ex){status("Could not save settings: "+message(ex));}}
    void status(String s){status.setText(s);status.setToolTipText(s);}
    void error(Throwable ex){String s=message(ex);status(s);JOptionPane.showMessageDialog(frame,s,"Anime Spawner",JOptionPane.ERROR_MESSAGE);}
    static String message(Throwable ex){while(ex.getCause()!=null)ex=ex.getCause();return ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage();}
    boolean overwrite(Path f){return !Files.exists(f)||JOptionPane.showConfirmDialog(frame,"Replace "+f.getFileName()+"?","File already exists",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    static Path extension(Path p,String ext){return p.toString().toLowerCase(Locale.ROOT).endsWith(ext)?p:Path.of(p+ext);}
    static JFileChooser chooser(String text,String...ext){JFileChooser fc=new JFileChooser();fc.setFileFilter(new FileNameExtensionFilter(text,ext));return fc;}
    static JPanel panel(LayoutManager l,Color c){JPanel p=new JPanel(l);p.setBackground(c);return p;}
    static JPanel vertical(Color c){JPanel p=panel(null,c);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p;}
    static JLabel label(String s,int size,Color c){JLabel l=new JLabel(s);l.setFont(new Font("Segoe UI",Font.PLAIN,size));l.setForeground(c);return l;}
    static JComponent wide(JComponent c){c.setMaximumSize(new Dimension(2000,40));c.setAlignmentX(Component.LEFT_ALIGNMENT);return c;}
    static JScrollPane scroll(Component c){JScrollPane s=new JScrollPane(c);s.setBorder(new LineBorder(LINE));s.getViewport().setBackground(BG);s.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);return s;}
    static JButton button(String text,boolean primary,Runnable task){JButton b=new JButton(text){@Override protected void paintComponent(Graphics gg){Graphics2D g=(Graphics2D)gg.create();Artwork.quality(g);Color base=getBackground();g.setColor(getModel().isPressed()?base.darker():getModel().isRollover()?base.brighter():base);g.fillRoundRect(0,0,getWidth(),getHeight(),10,10);g.dispose();super.paintComponent(gg);}};b.setBackground(primary?BLUE:INPUT);b.setForeground(TEXT);b.setFont(new Font("Segoe UI",primary?Font.BOLD:Font.PLAIN,12));b.setBorder(new EmptyBorder(12,15,12,15));b.setFocusPainted(false);b.setContentAreaFilled(false);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.addActionListener(e->task.run());return b;}
    final class AssetRenderer extends JPanel implements ListCellRenderer<Library.Asset>{Library.Asset a;boolean active;AssetRenderer(){setOpaque(false);}public Component getListCellRendererComponent(JList<? extends Library.Asset> l,Library.Asset value,int index,boolean selected,boolean focus){a=value;active=selected;return this;}protected void paintComponent(Graphics gg){Graphics2D g=(Graphics2D)gg.create();Artwork.quality(g);g.setColor(active?new Color(65,82,110):PANEL);g.fillRoundRect(5,4,getWidth()-10,getHeight()-8,12,12);if(active){g.setColor(BLUE);g.fillRoundRect(5,17,3,42,3,3);}BufferedImage im=a.clip!=null?a.clip.frames().get(0):null;g.setColor(new Color(31,34,42));g.fillRoundRect(17,14,49,49,10,10);if(im!=null){double scale=Math.min(49d/im.getWidth(),49d/im.getHeight());int w=(int)(im.getWidth()*scale),h=(int)(im.getHeight()*scale);g.drawImage(im,17+(49-w)/2,14+(49-h)/2,w,h,null);}else{g.setColor(MUTED);g.drawString("IMG",26,43);}g.setColor(TEXT);g.setFont(new Font("Segoe UI",Font.PLAIN,12));String name=a.name;while(name.length()>2&&g.getFontMetrics().stringWidth(name)>getWidth()-93)name=name.substring(0,name.length()-2)+"…";g.drawString(name,77,34);g.setColor(MUTED);g.setFont(new Font("Segoe UI",Font.PLAIN,10));g.drawString((a.favorite?"★  ":"")+a.type()+"  ·  "+(a.clip==null?"Ready":a.clip.frames().size()+" frames"),77,53);g.dispose();}}
    final class Preview extends JPanel {Preview(){setOpaque(true);setBackground(new Color(28,30,37));setBorder(new LineBorder(LINE));}protected void paintComponent(Graphics gg){super.paintComponent(gg);Graphics2D g=(Graphics2D)gg.create();Artwork.quality(g);int w=getWidth(),h=getHeight();g.setColor(new Color(42,45,55));for(int y=22;y<h;y+=22)for(int x=22;x<w;x+=22)g.fillOval(x,y,2,2);g.setColor(new Color(102,152,212));g.fillOval(16,17,6,6);g.setFont(new Font("Segoe UI",Font.PLAIN,10));g.setColor(MUTED);g.drawString(paused?"PREVIEW PAUSED":"LIVE PREVIEW",29,25);if(selected==null){
                g.setFont(new Font("Segoe UI",Font.PLAIN,20));g.setColor(TEXT);
                String title="Add your first animation";g.drawString(title,(w-g.getFontMetrics().stringWidth(title))/2,h/2-12);
                g.setFont(new Font("Segoe UI",Font.PLAIN,12));g.setColor(MUTED);
                String hint="Import a GIF or drop an image here";g.drawString(hint,(w-g.getFontMetrics().stringWidth(hint))/2,h/2+18);
            }
            if(previewClip!=null&&selected!=null){BufferedImage im=previewClip.at(previewTime);double s=Math.min((w-45d)/im.getWidth(),(h-100d)/im.getHeight());s=Math.min(s,1.25);int dw=(int)(im.getWidth()*s),dh=(int)(im.getHeight()*s),x=(w-dw)/2,y=(h-dh)/2;g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,(float)selected.opacity));g.drawImage(im,selected.flip?x+dw:x,y,selected.flip?-dw:dw,dh,null);g.setComposite(AlphaComposite.SrcOver);g.setColor(MUTED);g.setFont(new Font("Segoe UI",Font.PLAIN,11));String hint="Transparent background";g.drawString(hint,(w-g.getFontMetrics().stringWidth(hint))/2,h-22);}g.dispose();}}
    public static void main(String[] args){System.setProperty("sun.java2d.uiScale.enabled","true");Path data;
        try{Path location=Path.of(AnimeSpawner.class.getProtectionDomain().getCodeSource().getLocation().toURI());data=(Files.isDirectory(location)?location.getParent():location.getParent()).resolve("data");}catch(Exception ex){data=Path.of("data").toAbsolutePath();}
        for(int i=0;i<args.length-1;i++)if(args[i].equals("--data-dir"))data=Path.of(args[++i]).toAbsolutePath();final Path dir=data;
        Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(null,message(e),"Anime Spawner error",JOptionPane.ERROR_MESSAGE));});
        SwingUtilities.invokeLater(()->{try{new AnimeSpawner(dir).start();}catch(Exception ex){JOptionPane.showMessageDialog(null,"Could not start Anime Spawner: "+message(ex));}});
    }
